#include <fstream>
#include <iostream>
using namespace std;
int main() {
    fstream f("pos.bin", ios::in | ios::out | ios::binary | ios::trunc);
    f << "0123456789";
    f.seekg(-4, ios::end);
    char c; f.get(c);
    cout << c << ' ' << f.tellg() << ' ';
    f.seekp(2, ios::beg); f << "AB";
    f.seekg(-2, ios::cur); f.get(c);
    cout << c << ' ' << f.tellg();
}

