Rec is plain data, so its bytes can be written and read directly. What does this fragment print? It runs inside main() with <fstream>, <iostream> and <string> included and using namespace std; in effect.

struct Rec { int id; double marks; };
fstream f("rec.dat", ios::in | ios::out | ios::binary | ios::trunc);
for (int i = 1; i <= 4; i++) {
    Rec r = {i, i * 10.0};
    f.write(reinterpret_cast<char*>(&r), sizeof r);
}
Rec t;
f.seekg(2 * sizeof(Rec));
f.read(reinterpret_cast<char*>(&t), sizeof t);
cout << t.id << " " << t.marks << " ";
f.seekg(-static_cast<long>(sizeof(Rec)), ios::end);
f.read(reinterpret_cast<char*>(&t), sizeof t);
cout << t.id << " " << f.tellg() / sizeof(Rec);

