{ ofstream f("para.txt"); f << "to be\nor not\n"; }
ifstream in("para.txt");
char ch;
int lines = 0, words = 0, chars = 0;
bool inWord = false;
while (in.get(ch)) {
    chars++;
    if (ch == '\n') lines++;
    if (ch == ' ' || ch == '\n') inWord = false;
    else if (!inWord) { inWord = true; words++; }
}
cout << lines << " " << words << " " << chars;

